import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.simplepoint.platform.composition.ModuleCatalog;
import org.simplepoint.platform.composition.ModuleHttpPlan;
import org.simplepoint.platform.composition.ModuleMigrations;
import org.simplepoint.plugin.oidc.rest.configuration.OidcHttpModule;
import org.simplepoint.plugin.i18n.rest.configuration.I18nHttpModule;
import org.simplepoint.plugin.oidc.rest.controller.OidcClientController;
import org.simplepoint.plugin.i18n.rest.controller.I18nLanguagesController;
import org.springframework.security.access.prepost.PreAuthorize;

public class VerifyOptionalHttpArtifacts {
  public static void main(String[] args) throws Exception {
    var loader = VerifyOptionalHttpArtifacts.class.getClassLoader();
    var catalog = ModuleCatalog.discover(loader);
    var domain = catalog.plan(List.of("oidc", "i18n"));
    if (!ModuleHttpPlan.from(domain).routes().isEmpty()
        || domain.ownerOf(OidcClientController.class).isPresent()
        || domain.ownerOf(I18nLanguagesController.class).isPresent())
      throw new AssertionError("Domain selection still owns browser controllers");
    for (var type : List.of(OidcHttpModule.class, I18nHttpModule.class)) {
      if (type.getAnnotation(ModuleMigrations.class).ownsSchema())
        throw new AssertionError("HTTP adapter incorrectly owns a schema");
    }
    var selected = catalog.plan(List.of("oidc-http", "i18n-http"));
    var routes = ModuleHttpPlan.from(selected).routes();
    if (routes.get("oidc-http").size() != 2 || routes.get("i18n-http").size() != 6)
      throw new AssertionError("Missing shared namespace routes in distribution");
    for (var type : List.of(OidcHttpModule.class, I18nHttpModule.class,
        OidcClientController.class, I18nLanguagesController.class)) {
      if (Collections.list(loader.getResources(type.getName().replace('.', '/') + ".class")).size() != 1)
        throw new AssertionError("Missing/duplicate installed class: " + type.getName());
    }
    var expected = Map.of("limit", "view", "configuration", "view", "addConfiguration", "create",
        "modifyConfiguration", "edit", "add", "create", "modify", "edit", "remove", "delete");
    int checked = 0;
    for (var method : OidcClientController.class.getDeclaredMethods()) {
      if (!expected.containsKey(method.getName())) continue;
      var guard = method.getAnnotation(PreAuthorize.class);
      String expression = "hasRole('Administrator') or hasAuthority('oauthClients." + expected.get(method.getName()) + "')";
      if (guard == null || !guard.value().equals(expression))
        throw new AssertionError("Installed operation guard missing: " + method.getName());
      checked++;
    }
    if (checked != 7) throw new AssertionError("Incorrect guarded operation count");
    System.out.println("Installed distribution: domain-only isolation, two optional adapters, eight derived subtrees, unique classes and seven operation guards verified");
  }
}
